__global__
static void _floor(Real* y, const Real* x, Real floor_val, MatrixDim d, int src_stride) {
  int i = blockIdx.x * blockDim.x + threadIdx.x;  // col index
  int j = blockIdx.y * blockDim.y + threadIdx.y;  // row index
